#include "digitor/shader.hpp"
#include <regex>
#include <stdexcept>
namespace digitor { namespace { uint64_t hash(const std::string&s){uint64_t h=1469598103934665603ull;for(unsigned char c:s){h^=c;h*=1099511628211ull;}return h;} }
CompiledShader ShaderCompiler::compile(ShaderLanguage l,ShaderStage stage,const std::string&s){if(s.empty())throw std::invalid_argument("empty shader");CompiledShader out{l,{},s,{stage},hash(std::to_string((int)l)+s)};if(l==ShaderLanguage::spirv){if(s.size()%4)throw std::invalid_argument("SPIR-V byte size");for(size_t i=0;i<s.size();i+=4)out.spirv.push_back((uint8_t)s[i]|((uint8_t)s[i+1]<<8)|((uint8_t)s[i+2]<<16)|((uint8_t)s[i+3]<<24));if(out.spirv.empty()||out.spirv[0]!=0x07230203)throw std::invalid_argument("SPIR-V magic");}else{if(s.find("main")==std::string::npos)throw std::invalid_argument("shader has no entry point");std::regex binding(R"((?:binding\s*=\s*|register\s*\(\s*[tubs])(\d+))");for(std::sregex_iterator i(s.begin(),s.end(),binding),e;i!=e;++i)out.reflection.bindings.push_back({0,(uint32_t)std::stoul((*i)[1]),{}});std::regex local(R"(local_size_x\s*=\s*(\d+))");std::smatch m;if(std::regex_search(s,m,local))out.reflection.workgroup_size[0]=std::stoul(m[1]);}return out;}
const CompiledShader& ShaderCache::get_or_compile(ShaderCompiler&c,ShaderLanguage l,ShaderStage st,const std::string&s){auto k=std::to_string((int)l)+":"+std::to_string((int)st)+":"+s;auto it=entries_.find(k);if(it==entries_.end())it=entries_.emplace(k,c.compile(l,st,s)).first;return it->second;}
uint64_t PipelineCache::get_or_create(const std::vector<uint64_t>& shaders){std::string k;for(auto h:shaders)k+=std::to_string(h)+":";auto it=entries_.find(k);if(it==entries_.end())it=entries_.emplace(k,hash(k)).first;return it->second;}
}
